/**
 * FEMA recovery data from OpenFEMA, as generated by scripts/fema into
 * data/generated/fema-pr.json. The site never calls OpenFEMA: everything here
 * comes from committed files. Public Assistance project lists are separate
 * files per disaster, loaded only when someone opens that table.
 *
 * Kept apart on purpose:
 *   - Public Assistance (obligated federal share, project amount, total obligated),
 *   - household assistance FEMA approved (IHP),
 *   - Hazard Mitigation Assistance,
 *   - and USAspending (funds.ts). None of these is added to another.
 */
import fema from "../../../data/generated/fema-pr.json";
import { dayLabel as formatDay } from "../../i18n/format.ts";
import type { Locale } from "../../i18n/locale.ts";
import { FEMA_MESSAGES } from "../../i18n/messages/fema.ts";

export type FemaGeoState =
  | "MUNICIPIO_ATTRIBUTABLE"
  | "APPLICANT_MUNICIPIO"
  | "MUNICIPIO_UNCERTAIN"
  | "PUERTO_RICO_STATEWIDE"
  | "NO_MUNICIPIO_GEOGRAPHY";
export const FEMA_GEO_ORDER: FemaGeoState[] = [
  "MUNICIPIO_ATTRIBUTABLE",
  "APPLICANT_MUNICIPIO",
  "MUNICIPIO_UNCERTAIN",
  "PUERTO_RICO_STATEWIDE",
  "NO_MUNICIPIO_GEOGRAPHY",
];
export function femaGeoCopy(
  locale: Locale = "es",
): Record<FemaGeoState, { label: string; detail: string }> {
  return FEMA_MESSAGES[locale].geo;
}
export const FEMA_GEO_COPY = femaGeoCopy("es");

export type FemaMeasure =
  | "paObligated"
  | "paProjects"
  | "paProjectAmount"
  | "paTotalObligated"
  | "ihpApproved"
  | "ihpApprovedCount"
  | "ihpValidRegistrations"
  | "hmaFederalObligated"
  | "hmaProjects"
  | "hmaProjectAmount";

type Cell = ({ total: number | null } & Record<FemaGeoState, number | null>) | null;
export type FemaDisaster = {
  key: string;
  number: number | null;
  declaration: string | null;
  type: string | null;
  title: string | null;
  incidentType: string | null;
  declarationDate: string | null;
  incidentBegin: string | null;
  incidentEnd: string | null;
  closeoutDate: string | null;
  declaredInPuertoRico: boolean;
  programs: { ih: boolean; ia: boolean; pa: boolean; hm: boolean };
  statewideDesignation: boolean;
  designatedMunicipios: number;
  paProjectsFile: string | null;
};
type Dataset = {
  name: string;
  version: number;
  endpoint: string;
  page: string;
  lastRefresh: string | null;
  lastDataSetRefresh: string | null;
  nationalRecords: number | null;
  prRecords: number;
};
type Fema = {
  source: {
    publisher: string;
    api: string;
    retrievedAt: string;
    retrievedUntil: string;
    datasets: Record<
      "declarations" | "publicAssistance" | "mitigation" | "housingOwners" | "housingRenters",
      Dataset
    >;
    terms: { terms: string; disclaimer: string };
    attribution: string;
  };
  measures: FemaMeasure[];
  disasters: FemaDisaster[];
  municipios: Record<
    string,
    {
      name: string;
      designations: Record<string, [boolean, boolean, boolean, boolean]>;
      values: Record<string, (number | null)[]>;
    }
  >;
  island: Record<string, Record<FemaMeasure, Cell>>;
  hmaStatus: Record<string, Record<string, number>>;
  damageCategories: Record<string, string>;
  nulls: Record<string, number>;
};

const data = fema as unknown as Fema;

export const FEMA_SOURCE = data.source;
export const FEMA_DISASTERS = data.disasters;
export const FEMA_DAMAGE_CATEGORIES = data.damageCategories;
export const FEMA_NULLS = data.nulls;
/** "all": every disaster (and non-disaster mitigation) together. */
export const ALL = "all";
const index = (m: FemaMeasure) => data.measures.indexOf(m);

export function dayLabel(iso: string | null, locale: Locale = "es"): string {
  return formatDay(iso, locale);
}

/** "DR-4339-PR · HURRICANE MARIA (2017)" — FEMA's own identifier and title. */
export function disasterLabel(key: string, locale: Locale = "es"): string {
  const words = FEMA_MESSAGES[locale].disaster;
  if (key === ALL) return words.all;
  const d = data.disasters.find((x) => x.key === key);
  if (!d) return key;
  if (key === "none") return words.nonDisaster;
  if (!d.declaredInPuertoRico) return words.outside(d.number);
  return `${d.declaration} · ${d.title ?? words.untitled} (${d.declarationDate?.slice(0, 4) ?? "—"})`;
}

export function femaDisaster(key: string): FemaDisaster | null {
  return data.disasters.find((d) => d.key === key) ?? null;
}

const keysFor = (disaster: string) => (disaster === ALL ? Object.keys(data.island) : [disaster]);
/** Signed sum; null + null stays null (never 0). */
const plus = (a: number | null, b: number | null) => (b === null ? a : (a ?? 0) + b);

/** One measure for one municipio, for one disaster or all. Null when FEMA has nothing for it there. */
export function femaValue(id: string, measure: FemaMeasure, disaster: string = ALL): number | null {
  const row = data.municipios[id];
  if (!row) return null;
  let out: number | null = null;
  for (const key of keysFor(disaster)) out = plus(out, row.values[key]?.[index(measure)] ?? null);
  return out === null ? null : Math.round(out * 100) / 100;
}

/** Puerto Rico total of one measure and its geographic states. */
export function femaIsland(
  measure: FemaMeasure,
  disaster: string = ALL,
): { total: number | null } & Record<FemaGeoState, number | null> {
  const out = {
    total: null,
    MUNICIPIO_ATTRIBUTABLE: null,
    APPLICANT_MUNICIPIO: null,
    MUNICIPIO_UNCERTAIN: null,
    PUERTO_RICO_STATEWIDE: null,
    NO_MUNICIPIO_GEOGRAPHY: null,
  } as { total: number | null } & Record<FemaGeoState, number | null>;
  for (const key of keysFor(disaster)) {
    const cell = data.island[key]?.[measure];
    if (!cell) continue;
    out.total = plus(out.total, cell.total);
    for (const s of FEMA_GEO_ORDER) out[s] = plus(out[s], cell[s]);
  }
  return out;
}

/** Disasters that designated this municipio, newest first, with FEMA's program flags. */
export function designationsFor(
  id: string,
): { disaster: FemaDisaster; ih: boolean; ia: boolean; pa: boolean; hm: boolean }[] {
  const row = data.municipios[id];
  if (!row) return [];
  return data.disasters
    .filter((d) => row.designations[d.key])
    .map((d) => {
      const [ih, ia, pa, hm] = row.designations[d.key];
      return { disaster: d, ih, ia, pa, hm };
    });
}

export function hmaStatus(disaster: string = ALL): Record<string, number> {
  const out: Record<string, number> = {};
  for (const key of keysFor(disaster))
    for (const [s, n] of Object.entries(data.hmaStatus[key] ?? {})) out[s] = (out[s] ?? 0) + n;
  return out;
}

/** Disasters offered in the filter: those with any FEMA record for Puerto Rico, newest first. */
export const FEMA_FILTER: string[] = [
  ALL,
  ...data.disasters.filter((d) => data.island[d.key]).map((d) => d.key),
];

// Public Assistance project lists, one lazy chunk per disaster.
export type FemaProject = {
  pwNumber: number;
  /** P: applicant located in `municipio` (Public Assistance); S: Statewide; U: uncertain; N: none. */
  geo: "A" | "P" | "S" | "U" | "N";
  municipio: string | null;
  damageCategory: string;
  projectAmount: number | null;
  federalShareObligated: number | null;
  totalObligated: number | null;
  projectProcessStep: string | null;
  projectStatus: string | null;
  firstObligationDate: string | null;
  lastObligationDate: string | null;
};
const PROJECT_FILES = import.meta.glob<{
  default: { disaster: string; columns: string[]; rows: unknown[][] };
}>("../../../data/generated/fema-projects/*.json");

export async function loadProjects(disaster: string): Promise<FemaProject[]> {
  const loader = PROJECT_FILES[`../../../data/generated/fema-projects/${disaster}.json`];
  if (!loader) return [];
  const { default: file } = await loader();
  return file.rows.map((r) => {
    const [
      pwNumber,
      geo,
      municipio,
      damageCategory,
      projectAmount,
      federalShareObligated,
      totalObligated,
      projectProcessStep,
      projectStatus,
      firstObligationDate,
      lastObligationDate,
    ] = r as [
      number,
      FemaProject["geo"],
      string | null,
      string,
      number | null,
      number | null,
      number | null,
      string | null,
      string | null,
      string | null,
      string | null,
    ];
    return {
      pwNumber,
      geo,
      municipio,
      damageCategory,
      projectAmount,
      federalShareObligated,
      totalObligated,
      projectProcessStep,
      projectStatus,
      firstObligationDate,
      lastObligationDate,
    };
  });
}

/** The four map measures and the FEMA field each one sums (only money FEMA places in one municipio). */
export const FEMA_METRIC_MEASURE = {
  femaPaObligated: "paObligated",
  femaPaProjects: "paProjects",
  femaIhpApproved: "ihpApproved",
  femaHmaObligated: "hmaFederalObligated",
} as const satisfies Record<string, FemaMeasure>;
export type FemaMetricId = keyof typeof FEMA_METRIC_MEASURE;
export const FEMA_METRIC_IDS = Object.keys(FEMA_METRIC_MEASURE) as FemaMetricId[];

export function femaPlaceValues(
  id: string,
  disaster: string = ALL,
): Record<FemaMetricId, number | null> {
  return Object.fromEntries(
    FEMA_METRIC_IDS.map((m) => [m, femaValue(id, FEMA_METRIC_MEASURE[m], disaster)]),
  ) as Record<FemaMetricId, number | null>;
}
